#!/usr/bin/env node
// Generated-file drift gate. Re-runs the repo's own generators on a scratch
// copy of their inputs and compares what they write with the committed files,
// so it never touches the working tree (safe to run locally too):
//
//   app/scripts/inline-xterm.js  -> app/assets/xterm/terminal.bundle.html
//   scripts/make-logos.mjs       -> app/assets/*.png, web/public/ icons,
//                                   logo/favicon SVGs, site.webmanifest
//
// make-logos also draws app/android/ launcher icons; app/android/ is the
// gitignored prebuild output, so those are not compared. PNGs compare by
// header + inflated pixel stream: a different zlib build (another Node, CPU)
// may compress the same pixels to other bytes, which only warns.
//
// With app deps installed it also checks the vendored xterm copy
// (app/assets/xterm/xterm.{js,css}) is the locked @xterm/xterm release, so a
// dependency bump cannot ship the old terminal. --require-vendor fails
// instead of skipping when app/node_modules is missing (CI).
//
//   node .github/ci/js/check-generated.mjs [--require-vendor] [--keep]
import { spawnSync } from 'node:child_process';
import {
  cpSync,
  existsSync,
  mkdirSync,
  mkdtempSync,
  readFileSync,
  readdirSync,
  rmSync,
} from 'node:fs';
import { tmpdir } from 'node:os';
import { dirname, join, relative, sep } from 'node:path';
import { inflateSync } from 'node:zlib';
import { ROOT, bytes, createReport, summary } from './lib.mjs';

const args = new Set(process.argv.slice(2));
const r = createReport();

const GENERATORS = [
  {
    name: 'xterm page bundle',
    fix: './manage xterm',
    script: 'app/scripts/inline-xterm.js',
    inputs: [
      'app/assets/xterm/xterm.js',
      'app/assets/xterm/xterm.css',
      'app/assets/xterm/terminal.js',
      'app/assets/xterm/terminal.html',
    ],
    ignore: [],
  },
  {
    name: 'brand assets',
    fix: 'pnpm logos',
    script: 'scripts/make-logos.mjs',
    inputs: ['theme/tokens.json', 'theme/logo.json'],
    ignore: ['app/android/'],
  },
];

const PNG_SIG = Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]);

// IHDR bytes + the inflated IDAT stream: equal means equal pixels for the
// same filter choice (make-logos always writes filter 0).
function pngPixels(buf) {
  if (buf.length < 8 || !buf.subarray(0, 8).equals(PNG_SIG)) return null;
  let ihdr = null;
  const idat = [];
  for (let off = 8; off + 8 <= buf.length; ) {
    const len = buf.readUInt32BE(off);
    const type = buf.toString('ascii', off + 4, off + 8);
    const data = buf.subarray(off + 8, off + 8 + len);
    if (type === 'IHDR') ihdr = Buffer.from(data);
    if (type === 'IDAT') idat.push(data);
    off += 12 + len;
  }
  if (!ihdr || !idat.length) return null;
  try {
    return Buffer.concat([ihdr, inflateSync(Buffer.concat(idat))]);
  } catch {
    return null;
  }
}

function walk(dir, base = dir, out = []) {
  for (const entry of readdirSync(dir, { withFileTypes: true })) {
    const full = join(dir, entry.name);
    if (entry.isDirectory()) walk(full, base, out);
    else out.push(relative(base, full).split(sep).join('/'));
  }
  return out;
}

const scratchBase = process.env.RUNNER_TEMP || tmpdir();
const rows = [];

for (const gen of GENERATORS) {
  const box = mkdtempSync(join(scratchBase, 'pcd-generated-'));
  try {
    const copied = new Map();
    for (const rel of [gen.script, ...gen.inputs]) {
      const src = join(ROOT, rel);
      if (!existsSync(src)) {
        r.error(`generator input missing`, rel);
        continue;
      }
      mkdirSync(dirname(join(box, rel)), { recursive: true });
      cpSync(src, join(box, rel));
      copied.set(rel, readFileSync(src));
    }
    // The generators resolve their paths from their own location, so the
    // sandbox copy reads and writes only inside the sandbox.
    const run = spawnSync(process.execPath, [join(box, gen.script)], { cwd: box, encoding: 'utf8' });
    if (run.status !== 0) {
      r.error(`${gen.script} failed (exit ${run.status}):\n${run.stderr || run.stdout}`, gen.script);
      continue;
    }

    // Outputs = new files plus copied files the generator rewrote.
    const outputs = walk(box).filter((rel) => {
      if (gen.ignore.some((p) => rel.startsWith(p))) return false;
      const before = copied.get(rel);
      return !before || !before.equals(readFileSync(join(box, rel)));
    });
    if (!outputs.length) r.error(`${gen.script} wrote nothing`, gen.script);

    for (const rel of outputs.sort()) {
      const fresh = readFileSync(join(box, rel));
      const committed = join(ROOT, rel);
      let status;
      if (!existsSync(committed)) {
        status = '❌ not committed';
        r.error(`generated by ${gen.script} but missing from the repo; run \`${gen.fix}\` and commit it`, rel);
      } else {
        const have = readFileSync(committed);
        if (have.equals(fresh)) {
          status = '✅ identical';
        } else if (rel.endsWith('.png') && pngPixels(have)?.equals(pngPixels(fresh) ?? Buffer.alloc(0))) {
          status = '✅ same pixels (other zlib bytes)';
          r.warn(`same pixels, different compressed bytes (zlib build); not drift`, rel);
        } else {
          status = `❌ drift (${bytes(have.length)} committed, ${bytes(fresh.length)} generated)`;
          r.error(`out of date with ${gen.script}; run \`${gen.fix}\` and commit the result`, rel);
        }
      }
      rows.push(`| ${gen.name} | \`${rel}\` | ${status} |`);
    }
  } finally {
    if (args.has('--keep')) console.log(`kept sandbox ${box}`);
    else rmSync(box, { recursive: true, force: true });
  }
}

// ---------- vendored xterm == locked @xterm/xterm ----------
const pkgDir = join(ROOT, 'app/node_modules/@xterm/xterm');
if (existsSync(join(pkgDir, 'package.json'))) {
  const { version } = JSON.parse(readFileSync(join(pkgDir, 'package.json'), 'utf8'));
  for (const [from, to] of [
    ['lib/xterm.js', 'app/assets/xterm/xterm.js'],
    ['css/xterm.css', 'app/assets/xterm/xterm.css'],
  ]) {
    const same = existsSync(join(pkgDir, from)) && readFileSync(join(pkgDir, from)).equals(readFileSync(join(ROOT, to)));
    if (!same) {
      r.error(
        `is not @xterm/xterm@${version}/${from}; copy it from app/node_modules/@xterm/xterm, then run ./manage xterm`,
        to,
      );
    }
    rows.push(`| vendored xterm | \`${to}\` | ${same ? `✅ @xterm/xterm@${version}` : `❌ differs from @xterm/xterm@${version}`} |`);
  }
} else if (args.has('--require-vendor')) {
  r.error('app/node_modules/@xterm/xterm is missing; install app deps before this check');
} else {
  r.notice('app deps not installed; vendored xterm check skipped');
}

summary(['### Generated files', '', '| Source | File | Status |', '|---|---|---|', ...rows, ''].join('\n'));
r.finish('generated files');
